WITH RECURSIVE Months AS (SELECT 1 AS month UNION ALL SELECT month + 1 FROM Months WHERE month < 12) SELECT m.month, (SELECT COUNT(*) FROM Drivers d WHERE d.join_date <= LAST_DAY(CONCAT('2020-', LPAD(m.month, 2, '0'), '-01'))) AS active_drivers, (SELECT COUNT(*) FROM AcceptedRides ar JOIN Rides r ON ar.ride_id = r.ride_id WHERE YEAR(r.requested_at) = 2020 AND MONTH(r.requested_at) = m.month) AS accepted_rides FROM Months m ORDER BY m.month;
